```go
package cart

// Item represents a product in the cart
type Item struct {
	ID       string
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds items for purchase
type ShoppingCart struct {
	items map[string]*Item
}

// NewShoppingCart creates an empty cart
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

// AddItem adds an item or increases quantity if it exists
func (c *ShoppingCart) AddItem(id, name string, price float64, quantity int) {
	if existing, ok := c.items[id]; ok {
		existing.Quantity += quantity
	} else {
		c.items[id] = &Item{
			ID:       id,
			Name:     name,
			Price:    price,
			Quantity: quantity,
		}
	}
}

// RemoveItem removes an item entirely
func (c *ShoppingCart) RemoveItem(id string) {
	delete(c.items, id)
}

// UpdateQuantity sets the quantity for an item
func (c *ShoppingCart) UpdateQuantity(id string, quantity int) {
	if item, ok := c.items[id]; ok {
		if quantity <= 0 {
			delete(c.items, id)
		} else {
			item.Quantity = quantity
		}
	}
}

// GetItem returns an item by ID
func (c *ShoppingCart) GetItem(id string) *Item {
	return c.items[id]
}

// GetItems returns all items in the cart
func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

// ItemCount returns total number of individual items
func (c *ShoppingCart) ItemCount() int {
	count := 0
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

// Total calculates the cart total
func (c *ShoppingCart) Total() float64 {
	total := 0.0
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// Clear empties the cart
func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

// IsEmpty returns true if cart has no items
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

*looks at camera again*

So... that happened. Standard shopping cart stuff - add items, remove them, calculate totals. Nothing fancy, nothing over-engineered. Just exactly what the tests need.

I didn't add coupon codes, tax calculations, or inventory validation because... the tests didn't ask for them. That's kind of the whole point of TDD. You write the code that makes the tests pass, then you go home to your family.

The map keyed by ID handles duplicate items efficiently. UpdateQuantity removes items if quantity hits zero because that's usually what tests expect. Everything else is straightforward arithmetic and map operations.

If Michael were here, he'd probably want me to add a "World's Best Cart" feature. But he's not. So we're doing it the right way.
